.fanhui{
  position: fixed;
  left: 30px;
  top: 30px;
}
.ict_page111{
  background-repeat: no-repeat;
  position: relative;
  padding: 1px;
  user-select: none;
  &.topback1{
    background-image: url('./img/topback1.png');
  }
  &.topback2{
    background-image: url('./img/topback2.png');
  }
   &.topback3{
    background-image: url('./img/xc_bg.png');
  }
}
.ict_page{
  height: calc(100% - 20px);
  overflow-y: auto;

  // background-repeat: no-repeat;
  // position: relative;
  // padding: 1px;
  // user-select: none;
  // &.topback1{
  //   background-image: url('./img/topback1.png');
  // }
  // &.topback2{
  //   background-image: url('./img/topback2.png');
  // }
  //  &.topback3{
  //   background-image: url('./img/xc_bg.png');
  // }
  ::v-deep *{box-sizing: border-box;}
  .bottom_back{
    position: absolute;
    bottom: 0;
    width: 100%;
    height: calc(100% - 555px);
    background: linear-gradient(180deg, #fff 0%, rgba(206,229,255,0.8) 100%);
    display: none;
    z-index: -1;
  }
  .page_content{
    width: 1280px;
    margin: 0 auto;
    height: calc(100% - 350px);
    margin-top: 300px;
    // overflow-y: auto;
  }
  .tabs_header{
    width: 100%;
    height: 60px;
    padding: 0px 33px;
    box-sizing: border-box;
    border-radius: 10px;
    background: linear-gradient(180deg, #ffffff 0%, #c2d6ff 100%);
    box-shadow: 0px 4px 13px 0px rgba(255,255,255,0.25);
    display: flex;
    justify-content: space-between;
    align-items: center;
    opacity: 0.85;
    margin-bottom: 25px;
    &_item {
      color: #333;
      font-size: 18px;
      height: 45px;
      line-height: 45px;
      font-weight: bold;
      width: 387px;
      text-align: center;
      cursor: pointer;
    }
    &_item.is_active{
      background: linear-gradient(180deg, #109bff 0%, #022eff 85%, #0019ff 100%);
      box-shadow: 0px 4px 13px 0px rgba(255,255,255,0.5);
      border-radius: 6px;
      color: #fff;
    }
  }
  .tabs_content{
    // height: calc(100% - 85px);
    box-sizing: border-box;
    overflow-y: auto;
  }
}
